"""
Network for ECG beat classification (N / S / V / F), 1D CNN, input (1, 360).

Layers (same as src/model.py EdgeECGNet):
  conv1: 1 x 360  Conv1d(k=5, pad=2) + BN(folded) + ReLU  -> 16 x 360
  conv2: 16 x 360  MaxPool1d(2) -> Conv1d(k=5, pad=2) + BN(folded) + ReLU  -> 32 x 180
  conv3: 32 x 180  MaxPool1d(2) -> Conv1d(k=5, pad=2) + BN(folded) + ReLU  -> 32 x 90
  conv4: 32 x 90  MaxPool1d(2) -> Conv1d(k=3, pad=1) + BN(folded) + ReLU  -> 48 x 45
  conv5: 48 x 45  MaxPool1d(2) -> Conv1d(k=3, pad=1) + BN(folded) + ReLU  -> 64 x 22
  conv6: 64 x 22  MaxPool1d(2) -> Conv1d(k=1, pad=0) + BN(folded) + ReLU  -> 32 x 11
  fc: 32 x 11 = 352  Flatten -> Linear (32-bit output)  -> 4
"""
from torch import nn

import ai8x


class AI85ECGNet(nn.Module):
    """1D CNN for 4-class ECG beat classification (360 samples, 1 channel)."""

    def __init__(self, num_classes=4, num_channels=1, dimensions=(360, 1), bias=True, **kwargs):
        super().__init__()
        # The BatchNorm variants need bias=True: run train.py with --use-bias.
        self.conv1 = ai8x.FusedConv1dBNReLU(num_channels, 16, 5, stride=1, padding=2, bias=bias, **kwargs)
        self.conv2 = ai8x.FusedMaxPoolConv1dBNReLU(16, 32, 5, pool_size=2, pool_stride=2, stride=1, padding=2, bias=bias, **kwargs)
        self.conv3 = ai8x.FusedMaxPoolConv1dBNReLU(32, 32, 5, pool_size=2, pool_stride=2, stride=1, padding=2, bias=bias, **kwargs)
        self.conv4 = ai8x.FusedMaxPoolConv1dBNReLU(32, 48, 3, pool_size=2, pool_stride=2, stride=1, padding=1, bias=bias, **kwargs)
        self.conv5 = ai8x.FusedMaxPoolConv1dBNReLU(48, 64, 3, pool_size=2, pool_stride=2, stride=1, padding=1, bias=bias, **kwargs)
        self.conv6 = ai8x.FusedMaxPoolConv1dBNReLU(64, 32, 1, pool_size=2, pool_stride=2, stride=1, padding=0, bias=bias, **kwargs)
        self.drop = nn.Dropout(0.1)
        self.fc = ai8x.Linear(352, num_classes, bias=bias, wide=True, **kwargs)

    def forward(self, x):  # pylint: disable=arguments-differ
        """Forward prop"""
        x = self.conv1(x)
        x = self.conv2(x)
        x = self.conv3(x)
        x = self.conv4(x)
        x = self.conv5(x)
        x = self.conv6(x)
        x = x.view(x.size(0), -1)
        x = self.drop(x)
        x = self.fc(x)
        return x


def ai85ecgnet(pretrained=False, **kwargs):
    """Constructs the ECG network."""
    assert not pretrained
    return AI85ECGNet(**kwargs)


